<script setup lang="ts">
import {t} from "../i18n"
import { ref, computed, onMounted } from 'vue'
import { useQuasar } from 'quasar'
import { api, send } from '../api'
import { useCms } from '../store'
import Icon from './Icon.vue'
const cms = useCms(), q = useQuasar()
const data = ref<any>({ users: [], roles: [], permissions: [] }), loading = ref(false), saving = ref(false), error = ref(''), tab = ref('Accounts'), search = ref('')
const userDialog = ref(false), roleDialog = ref(false)
const userForm = ref<any>({}), roleForm = ref<any>({})
const users = computed(() => data.value.users.filter((u: any) => `${u.name} ${u.email}`.toLowerCase().includes(search.value.toLowerCase())))
const roleName = (id: number) => data.value.roles.find((r: any) => r.id === id)?.name || 'Unassigned'
const clone = (value: any) => JSON.parse(JSON.stringify(value))
async function load() { loading.value = true; error.value = ''; try { data.value = await api('/access') } catch (e: any) { error.value = e.message } finally { loading.value = false } }
function editUser(user?: any) { userForm.value = user ? { ...clone(user), password: '', password_confirmation: '', is_active: !!user.is_active } : { name: '', email: '', role_id: data.value.roles.find((r: any) => r.name === 'Editor')?.id, is_active: true, password: '', password_confirmation: '' }; userDialog.value = true }
function editRole(role?: any) { roleForm.value = role ? clone(role) : { name: '', permissions: ['read'] }; roleDialog.value = true }
async function saveUser() {
  saving.value = true
  try { const u = userForm.value; const payload = { ...u }; if (!payload.password) { delete payload.password; delete payload.password_confirmation }
    await api('/users' + (u.id ? '/' + u.id : ''), send(u.id ? 'PUT' : 'POST', payload)); userDialog.value = false; await load(); q.notify({ type: 'positive', message: t('Account saved. Assign website memberships to grant access to content.') })
  } catch (e: any) { q.notify({ type: 'negative', message: t(e.message) }) } finally { saving.value = false }
}
async function saveRole() { saving.value = true; try { const r = roleForm.value; await api('/roles' + (r.id ? '/' + r.id : ''), send(r.id ? 'PUT' : 'POST', r)); roleDialog.value = false; await load(); q.notify({ type: 'positive', message: t('Role permissions saved.') }) } catch (e: any) { q.notify({ type: 'negative', message: t(e.message) }) } finally { saving.value = false } }
function removeRole(role: any) { q.dialog({ title: t('Delete ' + role.name + '?'), message:t('Roles can only be deleted after every account and membership has been reassigned.'), cancel: true }).onOk(async () => { try { await api('/roles/' + role.id, { method: 'DELETE' }); await load() } catch (e: any) { q.notify({ type: 'negative', message: t(e.message) }) } }) }
onMounted(load)
</script>
<template><div class="page-wrap access-page"><div class="page-heading"><div><span class="eyebrow">{{ $t("PEOPLE, WITH THE RIGHT PERMISSIONS") }}</span><h1>{{ $t("Users & roles") }}</h1><p>{{ $t("Control workspace accounts and grant each website the team it needs.") }}</p></div><button v-if="!error" class="btn primary" @click="tab==='Accounts'?editUser():editRole()"><Icon name="Plus" :size="17"/>{{ $t(tab==='Accounts'?'Create account':'Create role') }}</button></div><q-linear-progress v-if="loading" indeterminate color="primary"/><div v-if="error" class="empty-state"><Icon name="LockKeyhole" :size="32"/><h2>{{ $t("Restricted workspace area") }}</h2><p>{{ error }}</p><button class="btn secondary" @click="load">{{ $t("Retry") }}</button></div><template v-else><div class="info-note" v-if="cms.mode.includes('preview')"><Icon name="Info"/><span>{{ $t("Local demonstration records only. Account sign-in, password enforcement and permission isolation must be verified against Laravel; the preview session always uses the demo administrator.") }}</span></div><div class="website-toolbar"><div class="filter-tabs"><button v-for="t in ['Accounts','Roles & permissions']" :class="{active:tab===t}" @click="tab=t">{{ $t(t) }}</button></div><div class="inline-search" v-if="tab==='Accounts'"><Icon name="Search" :size="16"/><input v-model="search" :placeholder="$t('Search people…')" :aria-label="$t('Search people')"></div></div><div v-if="tab==='Accounts'" class="table-panel"><table class="cms-table"><thead><tr><th>{{ $t("Person") }}</th><th>{{ $t("Workspace role") }}</th><th>{{ $t("Account status") }}</th><th></th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td><div class="person-cell"><span class="avatar">{{ user.name.split(' ').map((s:string)=>s[0]).slice(0,2).join('') }}</span><div><strong>{{ user.name }}</strong><small>{{ user.email }}</small></div></div></td><td>{{ $t(roleName(user.role_id)) }}</td><td><span :class="['status-pill',user.is_active?'published':'archived']">{{ $t(user.is_active?'Active':'Suspended') }}</span></td><td><button class="text-link" @click="editUser(user)">{{ $t("Manage account") }} <Icon name="ArrowRight" :size="15"/></button></td></tr></tbody></table><p v-if="!users.length" class="empty-text">{{ $t("No matching accounts.") }}</p><div class="table-footer">{{ users.length }} {{ $t("accounts") }}<span>{{ $t("Use each website’s Team tab to assign memberships.") }}</span></div></div><div v-else class="role-grid"><article v-for="role in data.roles" :key="role.id" class="panel role-card"><div class="section-heading"><h2>{{ $t(role.name) }}</h2><span class="language-badge">{{ $t(role.is_system?'Protected':'Custom') }}</span></div><p>{{ $t(role.permissions.includes('*')?'Full access within this role’s scope.':role.permissions.length+' capabilities enabled.') }}</p><div class="permission-chips"><span v-for="p in role.permissions">{{ $t(p==='*'?'All permissions':p) }}</span></div><div class="dialog-footer" v-if="!role.is_system"><button class="text-link" @click="editRole(role)">{{ $t("Edit permissions") }}</button><button class="icon-btn danger" @click="removeRole(role)" :aria-label="$t('Delete role')"><Icon name="Trash2" :size="17"/></button></div><p v-else class="role-footnote">{{ $t("Built-in roles are protected. Create a custom role to tailor access.") }}</p></article></div></template></div><q-dialog v-model="userDialog"><q-card class="standard-dialog"><h2>{{ $t(userForm.id?'Manage account':'Welcome someone new.') }}</h2><form @submit.prevent="saveUser"><q-input outlined v-model="userForm.name" :label="$t('Full name')" required maxlength="120"/><q-input outlined v-model="userForm.email" :label="$t('Email address')" type="email" required/><q-select outlined v-model="userForm.role_id" :options="$translatedOptions(data.roles.map((r:any)=>({label:r.name,value:r.id})))" emit-value map-options :label="$t('Workspace role')"/><q-toggle v-model="userForm.is_active" :label="$t('Account active')"/><p class="muted access-help">{{ $t("Suspension immediately blocks access in Laravel. At least one active Super Admin must remain.") }}</p><q-input outlined v-model="userForm.password" :label="$t(userForm.id?'New password (leave blank to keep)':'Initial password')" type="password" :required="!userForm.id" minlength="12" autocomplete="new-password" hint="12+ characters, upper/lowercase letters and a number."/><q-input outlined v-model="userForm.password_confirmation" :label="$t('Confirm password')" type="password" :required="!!userForm.password" autocomplete="new-password"/><div class="dialog-footer"><button class="btn secondary" type="button" @click="userDialog=false">{{ $t("Cancel") }}</button><q-btn type="submit" color="primary" unelevated :label="$t('Save account')" :loading="saving"/></div></form></q-card></q-dialog><q-dialog v-model="roleDialog"><q-card class="standard-dialog"><h2>{{ $t(roleForm.id?'Fine-tune permissions':'A role with purpose.') }}</h2><form @submit.prevent="saveRole"><q-input outlined v-model="roleForm.name" :label="$t('Role name')" required maxlength="100"/><p class="muted access-help">{{ $t("Read access is always included. These capabilities are enforced by the Laravel API.") }}</p><q-option-group v-model="roleForm.permissions" type="checkbox" :options="data.permissions.map((p:string)=>({label:p,value:p,disable:p==='read'}))" color="primary" class="permission-options"/><div class="dialog-footer"><button class="btn secondary" type="button" @click="roleDialog=false">{{ $t("Cancel") }}</button><q-btn type="submit" color="primary" unelevated :label="$t('Save role')" :loading="saving"/></div></form></q-card></q-dialog></template>
